exercises.solution:
const wielkaLiczba = 20000000000000000n;
const wynik = wielkaLiczba + 1n;
console.log(wynik, typeof wynik); // 20000000000000001n 'bigint'

const zwykla = 42;
const jakoBigInt = BigInt(zwykla);
console.log(jakoBigInt); // 42n

try {
  const wynik = 10n + 5;
} catch (e) {
  console.log(e.name); // "TypeError"
}

function bezpiecznyId(surowyId) {
  return BigInt(surowyId);
}

const id = bezpiecznyId("9223372036854775807");
console.log(id, typeof id); // 9223372036854775807n 'bigint'

const a = 10n;
const b = 3n;
console.log(a / b); // 3n
// dzielenie BigInt zawsze zwraca BigInt (liczba calkowita) -
// czesc ulamkowa jest ODRZUCANA (obciecie, nie zaokraglenie),
// wiec 10n / 3n daje 3n, NIE 3.333...n (ktore nie istnieje jako BigInt)

console.log(10n > 5); // true
// operatory porownania (<, >, <=, >=) DZIALAJA miedzy BigInt i Number
// bez jawnej konwersji i bez bledu - w odroznieniu od operatorow
// arytmetycznych (+, -, *, /), ktore wymagaja tego samego typu

console.log(10n === 10); // false - rozne typy (bigint vs number)
console.log(10n == 10);  // true - luzne porownanie konwertuje typy przed sprawdzeniem
// === wymaga IDENTYCZNEGO typu, wiec BigInt nigdy nie jest === Number,
// nawet dla tej samej wartosci liczbowej - == jest bardziej tolerancyjne

function formatujDuzaLiczbe(bigIntowa) {
  return `Wartosc: ${bigIntowa}`;
}

console.log(formatujDuzaLiczbe(123456789012345678901234567890n));
// Wartosc: 123456789012345678901234567890

console.log(Boolean(0n)); // false
console.log(Boolean(1n)); // true
// BigInt stosuje TE SAMA zasade truthy/falsy co Number:
// 0n jest falsy, kazda inna wartosc BigInt jest truthy

try {
  JSON.stringify({ id: 100n });
} catch (e) {
  console.log(e.name); // "TypeError"
}
// JSON nie ma formatu do reprezentowania BigInt - trzeba go recznie
// skonwertowac na string lub Number przed serializacja

function mnozBigInt(a, b) {
  return a * b;
}

console.log(mnozBigInt(999999999999999999n, 2n)); // 1999999999999999998n

const ujemna = -50n;
const wartoscBezwzgledna = ujemna < 0n ? -ujemna : ujemna;
console.log(wartoscBezwzgledna); // 50n
// Math.abs() (i wiekszosc metod Math) NIE dziala z BigInt -
// dla wartosci bezwzglednej trzeba samemu sprawdzic znak

function porownajWielkosci(a, b) {
  if (a > b) return "a wieksze";
  if (b > a) return "b wieksze";
  return "rowne";
}

console.log(porownajWielkosci(100000000000000000000n, 99999999999999999999n));
// "a wieksze"

function jestNiebezpieczna(liczba) {
  return liczba > Number.MAX_SAFE_INTEGER;
}

console.log(jestNiebezpieczna(Number.MAX_SAFE_INTEGER));      // false
console.log(jestNiebezpieczna(Number.MAX_SAFE_INTEGER + 10)); // true

function silniaBigInt(n) {
  let wynik = 1n;
  for (let i = 2; i <= n; i++) {
    wynik = wynik * BigInt(i);
  }
  return wynik;
}

console.log(silniaBigInt(20)); // 2432902008176640000n

function sumaZakresuBigInt(od, doWartosci) {
  let suma = 0n;
  for (let i = od; i <= doWartosci; i++) {
    suma = suma + BigInt(i);
  }
  return suma;
}

console.log(sumaZakresuBigInt(1, 100000)); // 5000050000n

const a = 7n;
const b = -7n;
console.log(a + b); // 0n

const tekstowaLiczba = "12345678901234567890";
console.log(BigInt(tekstowaLiczba)); // 12345678901234567890n - precyzyjnie
console.log(Number(tekstowaLiczba)); // 12345678901234567000 - UTRATA precyzji dla tak dlugiej liczby

function czyParzystaBigInt(n) {
  return n % 2n === 0n;
}

console.log(czyParzystaBigInt(10n)); // true
console.log(czyParzystaBigInt(7n));  // false

const bigIntowe = [3n, 1n, 4n, 1n, 5n];
let najwieksza = bigIntowe[0];
for (let i = 1; i < bigIntowe.length; i++) {
  if (bigIntowe[i] > najwieksza) {
    najwieksza = bigIntowe[i];
  }
}
console.log(najwieksza); // 5n

const tablica = ["a", "b", "c"];
console.log(tablica[2n]); // "c" - JS automatycznie konwertuje BigInt na string klucza
// dziala, bo dostep do tablicy przez [] wewnetrznie konwertuje
// indeks na string - ale to niestandardowa, rzadko stosowana praktyka,
// lepiej jawnie uzyc Number(bigIntowy) jako indeksu

function generujDuzeId() {
  const losowaCzesc = Math.floor(Math.random() * 1000000000);
  return BigInt(losowaCzesc) * 1n;
}

const id = generujDuzeId();
console.log(id, typeof id); // losowa wartosc, 'bigint'

function potegaBigInt(podstawa, wykladnik) {
  return podstawa ** wykladnik;
}

console.log(potegaBigInt(2n, 64n)); // 18446744073709551616n

const liczba = 42;
const bigIntowa = 42n;
console.log(Object.is(liczba, bigIntowa)); // false
// Object.is, podobnie jak ===, uwzglednia typ wartosci -
// Number 42 i BigInt 42n sa uznawane za ROZNE, mimo tej samej
// 'wartosci liczbowej', bo naleza do dwoch odrebnych typow prymitywnych

function bezpieczneDodawanie(a, b) {
  if (a + b > Number.MAX_SAFE_INTEGER) {
    return BigInt(a) + BigInt(b);
  }
  return a + b;
}

console.log(bezpieczneDodawanie(5, 10)); // 15
console.log(bezpieczneDodawanie(Number.MAX_SAFE_INTEGER, 100)); // 9007199254741091n

const identyfikatory = ["123456789012345678901", "987654321098765432109"];
const jakoBigInt = identyfikatory.map(BigInt);
console.log(jakoBigInt);
// [123456789012345678901n, 987654321098765432109n]

